def variants(old, new):
    yield old, new
    jo, jn = json.dumps(old)[1:-1], json.dumps(new)[1:-1]
    if jo != old:
        yield jo, jn
    ja, jna = json.dumps(old, ensure_ascii=False)[1:-1], json.dumps(new, ensure_ascii=False)[1:-1]
    if ja not in (old, jo):
        yield ja, jna


files = {p: p.read_text(encoding='utf-8') for p in sorted(OUT.glob('*.html'))}
missed = []
for old, new in EDITS:
    assert '—' not in new, new
    hit = 0
    for p in files:
        for o, n in variants(old, new):
            c = files[p].count(o)
            if c:
                files[p] = files[p].replace(o, n)
                hit += c
    if not hit:
        missed.append(old)

for p, t in files.items():
    p.write_text(t, encoding='utf-8')

if missed:
    print('MISSED %d:' % len(missed))
    for m in missed:
        print('  ' + m[:110])
    sys.exit(1)
print('plain: %d edits applied' % len(EDITS))
